class RtgUe(LteUe):
    """RtgUe"""

    def __init__(self, name, rpc_socket, ue_id, configuration=None, create_msg_src_id=True):
        """
        Definition of Abstract UE API
        :param name: name of UE to be stored inside UE object
        """
        super(RtgUe, self).__init__(name, configuration)
        self.rpc_socket = rpc_socket
        self._ue_id = ue_id
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self._ue_id})
        self.attached = False
        self.ue_stats_started = False
        self.device_definition = {'device_name': 'UE', 'device_id': self._ue_id}
        self.ne_id = UeIdentification(identifiers=[('rtg', self._ue_id)], network_elem_type='UE',
                                      specific_for_tool='rtg')
        self.rpc_call = RpcCall(rpc_socket, self.logger).call
        self.pdns = {}  # map pnd APN name to default EPS bearer ID
        # inform that UE is messaging-capable
        if create_msg_src_id:
            MsgSourceIdentification(identifiers=[('rtg', 'RTG')], network_elem_type='UE', specific_for_tool='rtg')

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Basic <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def attach(self, **attach_params):
        """
        Perform attach on UE.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        params = {"ue_id": self._ue_id, 'cause': None}
        params.update({"cause": self._get_rrc_conn_cause_value(attach_params)})
        if 'selected_plmn' in attach_params:
            params.update({"selected_plmn": self._get_seclected_plmn(attach_params['selected_plmn'])})

        response = self.rpc_call(method="attach", params=params, log_msg="UE({0}) - Attach".format(self._ue_id))
        self.attached = True

        # TODO workaround solution, implementation in UEx needed
        eps_bearer_id = response["eps_id"]
        nas_payload_bin = response["attachAccept"]

        nas_payload_dict = parse_nas_container(information_element='<<', hex_to_be_parsed=nas_payload_bin)
        try:
            default_bearer_qci = int(nas_payload_dict['ESMMsg']['EPSQoS']['QCI'])
            pdn_apn = nas_payload_dict['ESMMsg']['AP_Name']
        except KeyError as err:
            raise UeProcedureError('Failed to fetch Bearer QCI and/or PDN parameter. {}'.format(err))

        qci_pdn = {"qci": default_bearer_qci, "pdn": pdn_apn}
        self.pdns[pdn_apn] = eps_bearer_id

        default_bearer = self._create_bearer(bearer_id=eps_bearer_id, **qci_pdn)
        self.bearers.append(default_bearer)

    def detach(self, **detach_params):
        """
        Perform detach on UE.

        No action if UE is already detached.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If detach failed
        """
        params = {"ue_id": self._ue_id}
        if 'switch_off' in detach_params:
            if detach_params['switch_off'] == 'true':
                params['switch_off'] = True
            elif detach_params['switch_off'] == 'false':
                params['switch_off'] = False
            else:
                raise ValueError("switch_off value should be true or false")

        if 'ue_stats_started' in dir(self) and self.ue_stats_started:
            self.stop_collecting_ue_statistics()
        self.rpc_call(method="detach", params=params, log_msg="UE({0}) - Detach".format(self._ue_id))
        self.attached = False
        self.bearers = []

    def kill_ue(self):
        """Silently deactivates UE"""
        self.rpc_call(method="kill_ue", params=self._ue_id, log_msg="UE({0}) - kill ue".format(self._ue_id))
        self.attached = False
        self.bearers = []

    def get_ue_id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self._ue_id

    def handover(self, target_cell):
        """Perform handover on UE."""
        params = {"ue_id": self._ue_id, "sector_id": target_cell.sector_id}
        self.rpc_call(method="handover", params=params, log_msg="Handover")

    def reestablish(self, cause=None, cell='current_cell', **kwargs):
        """Perform reestablishment on UE."""
        if cell == 'current_cell':
            target_cell = None
        else:
            target_cell = cell.sector_id
        params = {"ue_id": self._ue_id, "target_cell": target_cell, 'cause': cause}
        self.rpc_call(method="reestablish", params=params, log_msg="UE({0}) - Reestablishment".format(self._ue_id))

