    def shutdown(self):
        """Shutdown UE"""
        self.logger.info('UE({0}) - Shutdown started'.format(self.name))
        if 'ue_stats_started' in dir(self) and self.ue_stats_started:
            self.stop_collecting_ue_statistics()

        self.rpc_call(method="cleanup_ue", params=self._ue_id, log_msg="UE({0}) - Shutdown".format(self._ue_id))
        self.attached = False
        self.bearers = []

        self.logger.info('UE({0}) - Shutdown succeeded'.format(self.name))

    def set_ue_location(self, cell):
        """
        Set UE location by performing UEx's UE.camp_on/2:
        :param cell:
        """
        if self.attached:
            raise UeProcedureError("Cannot set UE location: UE is attached")
        else:
            params = {"ue_id": self._ue_id, "sector_id": cell.sector_id}
            self.rpc_call(method="set_location", params=params, log_msg="UE({0}) - Setting UE location".format(self._ue_id))

    def set_ue_coverage_level(self, ce_level):
        """
        Set Coverage Enhancement level for ue:
        :param cell:
        """
        if self.attached:
            raise UeProcedureError("Cannot set coverage level when UE is attached")
        else:
            try:
                ce_level = int(ce_level)
            except AttributeError:
                raise ValueError("parameter ce_level should be an integer")
            if ce_level not in range(0, 4):
                raise ValueError("parameter ce_level should be 0,1,2 or 3")
            params = {"ue_id": self._ue_id, "ce_level": ce_level}
            self.rpc_call(method="set_coverage_level", params=params, log_msg="UE({0}) - Setting UE coverage level".format(self._ue_id))

    def set_ue_pathloss(self, pathloss):
        """Set PathLoss for UE"""
        if self.attached:
            raise UeProcedureError("Cannot set pathloss: UE is attached")
        else:
            params = {"ue_id": self._ue_id, "pathloss": int(pathloss)}
            self.rpc_call(method="set_pathloss", params=params, log_msg="UE({0}) - Setting UE PathLoss".format(self._ue_id))

    def get_ue_crnti(self):
        """Get C-RNTI value of UE"""
        params = {"ue_id": self._ue_id}
        crnti = self.rpc_call(method="get_ue_crnti", params=params, log_msg="UE({0}) - Getting UE C-RNTI".format(self._ue_id))
        if crnti:
            return crnti
        else:
            raise UeProcedureError("failed to fetch C-RNTI, probably UE is not in a connected state")

    def _get_rrc_conn_cause_value(self, attach_params):
        possibe_cause_list = ['defaultCause', 'emergency', 'highPriorityAccess', 'mt-Access', 'mo-Signalling',
                              'mo-Data', 'delayTolerantAccess-v1020', 'mo-VoiceCall-v1280', 'spare1']

        if 'rrcConnCause' in attach_params and 'establishmentCause' in attach_params:
            raise AttributeError("'rrcConnCause' and 'establishmentCause' cannot be provided both.")
        elif 'rrcConnCause' in attach_params:
            self.logger.warning("Please use 'establishmentCause' instead of 'rrcConnCause' as attach parameter")

        rrc_conn_cause = attach_params.get('establishmentCause') or attach_params.get('rrcConnCause')

        if rrc_conn_cause and rrc_conn_cause not in possibe_cause_list:
            raise AttributeError(
                "Invalid value for establishmentCause option. Possible values are: {}".format(possibe_cause_list))

        return rrc_conn_cause

    def _get_seclected_plmn(self, selected_plmn):
        try:
            return int(selected_plmn)
        except ValueError:
            status = re.search(r'(\d+):(\d+)', selected_plmn)
            try:
                mcc = status.group(1)
                mnc = status.group(2)
                return {'mcc': mcc, 'mnc': mnc}
            except AttributeError:
                raise ValueError('Invalid selected_plmn parameter, it should be an integer or MCC:MNC')

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Bearer <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    @staticmethod
    def _chcek_qci(qci):
        qci = int(qci)
        if (qci >= 1 and qci <= 9) or (qci >= 128 and qci <= 254):
            return qci
        else:
            raise UeProcedureError("QCI={} is invalid".format(qci))

    def activate_dedicated_bearer(self, bearer_type, **activation_params):
        """
        Performs dedicated bearer activation initiated from UE side.
        :param bearer_type: Bearer type object
        :param activation_params: depends on UE type
        :return: None
        """
        qci = self._chcek_qci(bearer_type.bearer_identification['qci'])
        pdn = bearer_type.bearer_identification['pdn']

        bearer_qos = {'mbr_dl': None, 'mbr_ul': None, 'gbr_dl': None, 'gbr_ul': None}
        if activation_params is not None:
            for key, value in activation_params.items():
                if key in ('mbr_dl', 'mbr_ul', 'gbr_dl', 'gbr_ul'):
                    bearer_qos.update({key: int(value)})
                else:
                    raise BearerCreationImpossible("Invalid bearer activation parameter: {}".format(key))

        if not self.bearer_is_active(bearer_type):
            if pdn not in self.pdns:
                raise BearerCreationImpossible("UE({0}) - UE is not connected to PDN with APN={0}".format(pdn))
            default_eps_id = self.pdns[pdn]
            params = {"ue_id": self._ue_id, "qci": qci, "eps_id": default_eps_id}
            params.update(**bearer_qos)

            bearer_id = self.rpc_call(method="activate_bearer", params=params, log_msg="UE({0}) - Bearer activation".format(self._ue_id))
            # TODO on failure, when no mbr/gbr specified inform that mbr/gbr parameters are required
            bearer = self._create_bearer(bearer_id, qci, pdn, **activation_params)
            self.bearers.append(bearer)
        else:
            self.logger.warning('UE({0}) - Bearer (qci: {1}, pdn: {2}) already activated'.format(self._ue_id, qci, pdn))

    def activate_dedicated_bearers(self, bearers):
        """
        :param bearers:
        :return:
        """
        for _, bearer in bearers.items():
            bearer_type = bearer['bearer_type']
            bearer_params = dict(param.split('=') for param in bearer['params'].split(' '))
            self.activate_dedicated_bearer(bearer_type, **bearer_params)

    def send_measurements(self, raw_params=None, **parameters):
        """Start sending measurements"""
        if raw_params:
            self.rpc_call(method="send_measurements", params={'ue_id': self._ue_id, 'raw_params': raw_params})
        else:
            uex_meas = RtgMeasurements(params=parameters).get_measurements()
            self.rpc_call(method="send_measurements", params={'ue_id': self._ue_id, 'meas': uex_meas})

    def stop_sending_measurements(self):
        """Stop sending measurements"""
        self.rpc_call(method="stop_sending_measurements", params={'ue_id': self._ue_id})

    def modify_bearer(self, bearer_type, **modification_params):
        """
        Performs UE initiated request for dedicated bearer modification.
        :param bearer_type: BearerType object
        :param modification_params:
        :return: None
        """
        raise NotImplementedError

    def deactivate_dedicated_bearer(self, bearer_type, **deactivation_params):
        """
        Performs UE initiated request for dedicated bearer deactivation.
        :param bearer_type: BearerType object
        :param deactivation_params: deactivation_params
        :return: None
        """
        qci = self._chcek_qci(bearer_type.bearer_identification['qci'])
        pdn = bearer_type.bearer_identification['pdn']
        if self.bearer_is_active(bearer_type):
            rtg_bearer = self._get_rtg_type_bearer(bearer_type)
            params = {"ue_id": self._ue_id, "bearer_id": rtg_bearer.get_bearer_id()}

            self.rpc_call(method="deactivate_bearer", params=params, log_msg="UE({0}) - Bearer deactivation".format(self._ue_id))
            self.bearers.remove(rtg_bearer)
        else:
            self.logger.error('UE({}) - Bearer (qci: {}, pdn: {}) already deactivated'.format(self._ue_id, qci, pdn))
            raise UeProcedureError('UE({}) - Bearer (qci: {}, pdn: {}) already deactivated'.format(self._ue_id, qci, pdn))

