    def _create_data_transfer(self, name, dt_definition):
        """
        Creating RtgDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: data_transfer: object derivered from lte_data_transfer class
        """
        dt_definition.bearer = self._get_rtg_type_bearer(dt_definition.bearer)
        data_transfer = RtgDataTransfer(name, dt_definition, self._configuration, logger_name=self.ue_logger_name,
                                        rpc_socket=self.rpc_socket, _ue_id=self._ue_id)
        scope.current_scope().uses(resource=data_transfer, resource_releaser=lambda arg: None)
        return data_transfer

