    # <=><=><=><=><=><=><=><=><=><=><=><=><=> Messaging <=><=><=><=><=><=><=><=><=><=><=><=><=>
    def drop_msg(self, message, number="any"):
        """Drop UE realted RRC/S1AP/X2AP message"""
        proto, msg = self._decode_message(message)
        params = {"ue_id": self._ue_id, 'protocol': proto, 'message': msg, 'number': number}
        self.rpc_call(method="drop_message", params=params, log_msg="UE({0}) - {1} subscription for drop".format(self._ue_id, message))

    def delay_msg(self, message, delay, number="any"):
        """Delay UE realted RRC/S1AP/X2AP message"""
        proto, msg = self._decode_message(message)
        delay = int(convert_timestring(delay) * 1000)
        params = {"ue_id": self._ue_id, 'protocol': proto, 'message': msg, 'delay': delay, 'number': number}
        self.rpc_call(method="delay_message", params=params, log_msg="UE({0}) - {1} subscription for delay".format(self._ue_id, message))

    def _decode_message(self, message):
        [proto, msg] = message.split('_')
        if msg[:3] == 'RRC':
            for key, val in rrc.items():
                if msg == val:
                    msg = key
                    break
            # msg = msg[:3].lower() + msg[3:]

        if proto not in ['RRC', 'S1AP', 'X2AP']:
            raise Exception("Wrong message protocol {}".format(proto))

        return proto, msg

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> PHY Statistics <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def start_collecting_ue_statistics(self, interval=None):
        """
        Start collecting ue statistics
        :param interval:
        :return:
        """
        if interval:
            interval = int(interval)
        if not self.attached:
            raise UeProcedureError("UE must be in active state")
        elif self.ue_stats_started:
            raise UeProcedureError("UE statistics collection already started")
        else:
            params = {"ue_id": self._ue_id, "interval": interval}
            self.rpc_call(method="start_collecting_ue_stats", params=params, log_msg="UE({0}) - Starting UE stats collection".format(self._ue_id))
            self.ue_stats_started = True

    def stop_collecting_ue_statistics(self):
        """Stop collecting ue statistics"""
        if self.ue_stats_started:
            params = {"ue_id": self._ue_id}
            self.rpc_call(method="stop_collecting_ue_stats", params=params, log_msg="UE({0}) - Stopping UE stats collection".format(self._ue_id))
            self.ue_stats_started = False
        else:
            raise UeProcedureError("UE statistics collection not started")

