    def verify_mac_throughput(self, tput_min, tput_max=None, direction="dl", function="current", bearer=None, scell="both"):
        """
        Verify MAC throughput
        :param tput_min:
        :param tput_max:
        :param direction:
        :param function: one of "maximum", "minimum", "average", "current"
        :param bearer:
        :param scell:
        :return:
        """
        tput = self.get_mac_throughput(direction, function, bearer, scell)
        self._verify_throughput(tput / 1000, tput_min, tput_max)

    def get_mac_throughput(self, direction, function, bearer=None, scell="both"):
        """
        Return MAC throughput in bps
        :param direction: "dl" or "ul"
        :param function: one of "maximum", "minimum", "average", "current"
        :param bearer:
        :param scell:
        :return:
        """
        bearer = self._get_bearer_id(bearer) if bearer else None
        self._check_mac_throughput_params(direction, function, bearer, scell)
        if self.ue_stats_started:
            params = {"ue_id": self._ue_id, "direction": direction, "meas_type": function, "bearer": bearer, "scell": scell}
            phy_throughput = self.rpc_call(method="get_ue_mdm_stats", params=params, log_msg="UE({0}) - Fetching UE stats".format(self._ue_id))
            self.logger.info("{} {} (scell eq '{}') throughput equals {} bps".format(function.capitalize(), direction.upper(), scell, phy_throughput))
            return phy_throughput
        else:
            raise UeProcedureError("UE statistics collection not started")

    def _get_bearer_id(self, bearer_type):
        required_pdn = bearer_type.bearer_identification['pdn']
        required_qci = int(bearer_type.bearer_identification['qci'])
        for bearer in self.bearers:
            if bearer.bearer_identification['rtg']['pdn_id'] == required_pdn and bearer.bearer_identification['rtg']['qci'] == required_qci:
                return bearer.bearer_identification['rtg']['bearer_id']
        raise ValueError("Invalid bearer provided")

    def _check_mac_throughput_params(self, direction, function, bearer_alias, scell):
        if direction not in ["ul", "dl"]:
            raise ValueError("Invalid parameter direction, it should be either 'ul' or 'dl'")
        if function not in ["current", "average", "maximum", "minimum"]:
            raise ValueError("Invalid parameter function, it should be either 'current', 'average', 'maximum', 'minimum'")
        if scell not in ["primary", "secondary", "both"]:
            raise ValueError("Invalid parameter direction, it should be either 'primary', 'secondary' or 'both'")
        # if bearer_alias:
        #     raise NotImplementedError("MAC throughput statistics per bearer are not yet avalible")

    def _verify_throughput(self, tput, tput_min, tput_max=None):
        normalized_tput_min = tput_user_value2normalized(tput_min)
        if tput < normalized_tput_min:
            msg = 'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  'Actual tput={tput} [kbits/sec]'.format(normalized_tput_min=normalized_tput_min,
                                                          tput=tput)
            self.stop_collecting_ue_statistics()
            raise Exception(msg)
        if tput_max and tput > tput_user_value2normalized(tput_max):
            msg = 'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  'Expected tput_max={normalized_tput_max} [kbits/s] \n' \
                  'Actual tput={tput} [kbits/sec]'.format(normalized_tput_min=normalized_tput_min,
                                                          normalized_tput_max=tput_user_value2normalized(tput_max),
                                                          tput=tput)
            self.stop_collecting_ue_statistics()
            raise Exception(msg)

